                    body = response.json() if content_type.startswith("application/json") else response.text

                    return json.dumps({"status": response.status_code, "body": body})

                return handler

            server.add_tool(
                name=operation_id,
                description=description,
                inputSchema=input_schema,
                handler=make_handler(path, method, parameters, bool(request_body))
